  "feat.f2t": "Che thông tin thực sự",
  "feat.f2b": "Các trang bị che được dựng lại để chữ bị ẩn biến mất hẳn, chứ không chỉ bị phủ một ô đen.",
  "feat.f3t": "Bản scan tìm kiếm được ở mọi ngôn ngữ",
