  "ai.models": "AI trên thiết bị",
  "ai.modelsNote": "Không bắt buộc. Mô hình tải một lần từ trang này, sau đó chạy ngoại tuyến. Tệp của bạn không bao giờ rời khỏi thiết bị này.",
  "ai.noWebgpu": "Trình duyệt này không có WebGPU, nên mô hình ngôn ngữ sẽ chạy chậm ở đây.",
  "ai.model.light": "Nhẹ",
  "ai.model.light.desc": "Tìm những câu trả lời theo nghĩa, không chỉ theo từ. Mọi thiết bị.",
  "ai.model.small": "Mô hình nhỏ (SmolLM2)",
  "ai.model.small.desc": "Viết câu trả lời và tóm tắt bằng tiếng Anh. Cần máy tính đời mới.",
  "ai.model.large": "Mô hình lớn (Qwen3)",
  "ai.model.large.desc": "Viết và dịch bằng nhiều ngôn ngữ. Cần máy tính đời mới.",
  "ai.remove": "Gỡ {name} khỏi thiết bị này",
  "ai.downloadFailed": "Quá trình tải bị dừng. Hãy thử lại: sẽ tiếp tục từ chỗ đã dừng.",
  "ai.server": "AI máy chủ",
  "ai.server.desc": "Được đề xuất cho thiết bị này. Câu trả lời, bản tóm tắt và bản dịch được viết sẵn, không cần tải gì về.",
  "ai.server.who": "Dữ liệu được gửi qua kết nối mã hóa đến các dịch vụ AI mà chúng tôi sử dụng. Chúng tôi không lưu trữ, và họ không dùng nó để huấn luyện AI.",
  "ai.server.more": "Những dịch vụ nào, và họ xử lý văn bản của bạn ra sao",
  "ai.capable.chat": "Thiết bị này có thể tự chạy AI, nên AI ở đây chạy trên thiết bị của bạn: không có gì bạn thêm vào được gửi đi đâu cả, và vẫn hoạt động khi ngoại tuyến. Tải Mô hình nhỏ hoặc Mô hình lớn một lần để nhận câu trả lời được viết ra, hoặc Nhẹ để tìm câu theo nghĩa. Cho đến lúc đó, bạn nhận được các câu trong PDF khớp với từ của bạn.",
  "ai.capable.summarize": "Thiết bị này có thể tự chạy AI, nên AI ở đây chạy trên thiết bị của bạn: không có gì bạn thêm vào được gửi đi đâu cả, và vẫn hoạt động khi ngoại tuyến. Tải Mô hình nhỏ hoặc Mô hình lớn một lần để có bản tóm tắt được viết ra. Cho đến lúc đó, bản tóm tắt gồm các câu then chốt của chính tài liệu, hoặc do AI tích hợp của trình duyệt viết nếu trình duyệt có.",
  "ai.capable.translate": "Thiết bị này có thể tự chạy AI, nên việc dịch chạy trên thiết bị của bạn: không có gì bạn thêm vào được gửi đi đâu cả, và vẫn hoạt động khi ngoại tuyến. Tải Mô hình lớn một lần (570 MB) để dịch, trừ khi trình duyệt của bạn đã có sẵn trình dịch tích hợp cho các ngôn ngữ của bạn.",
  "ai.capable.why": "AI máy chủ được dành cho điện thoại và thiết bị cũ không chạy được mô hình, để nó luôn miễn phí cho mọi người. Nếu một mô hình chạy không tốt ở đây, AI máy chủ sẽ được đề xuất thay thế.",
  "ai.deviceFailed": "Mô hình AI chạy không tốt trên thiết bị này, nên AI máy chủ được đề xuất thay thế.",
  "ai.device.limitsPhone": "Trên điện thoại, AI trên thiết bị chỉ có thể hiển thị các câu khớp trong PDF: các mô hình AI quá lớn để tải xuống và chạy trên điện thoại. AI máy chủ đưa ra câu trả lời bằng văn bản và bản tóm tắt.",
  "ai.device.limitsPhoneTranslate": "Trên điện thoại, dịch trên thiết bị chỉ hoạt động nếu trình duyệt của bạn có sẵn trình dịch tích hợp cho các ngôn ngữ của bạn, điều mà trình duyệt điện thoại hiếm khi có: các mô hình AI quá lớn đối với điện thoại. AI máy chủ dịch được sang bất kỳ ngôn ngữ nào của trang web.",
  "ai.where": "Nơi AI chạy",
  "ai.server.sends.chat": "PDF của bạn vẫn ở trên thiết bị này. Để trả lời, câu hỏi của bạn, các câu hỏi trước đó trong cuộc trò chuyện này và những đoạn trong PDF khớp với câu hỏi sẽ được gửi đi.",
  "ai.server.sends.summarize": "PDF của bạn vẫn ở trên thiết bị này. Để tóm tắt, văn bản của nó được gửi đi: khoảng 15.000 từ đầu tiên, cùng các câu then chốt khi tài liệu dài hơn.",
  "ai.server.sends.translate": "PDF của bạn vẫn ở trên thiết bị này. Để dịch, văn bản của nó được gửi đi từng vài khối một, và bản dịch được đặt lại vào PDF ngay tại đây.",
  "ai.device": "Trên thiết bị này",
  "ai.device.desc": "Không có gì được gửi đi đâu cả, và vẫn hoạt động khi ngoại tuyến.",
  "ai.device.limits": "Điều bạn phải đánh đổi: câu trả lời và bản tóm tắt đơn giản hơn và kém chính xác hơn. Nếu không tải về, bạn nhận được các câu được chọn từ PDF chứ không phải câu trả lời được viết ra. Các mô hình có thể viết cần tải về từ 270 đến 570 MB, cần máy tính đời mới, và chạy chậm hoặc có thể không chạy được trên điện thoại và thiết bị cũ.",
  "ai.device.limitsTranslate": "Việc dịch còn cần trình dịch tích hợp của trình duyệt (Chrome trên máy tính có sẵn) hoặc Mô hình lớn 570 MB.",
