  "chat.by.server": "Do AI máy chủ viết từ các trang được trích dẫn. Hãy kiểm tra các trang đó cho mọi điều quan trọng.",
  "chat.cloudFailed": "AI máy chủ không phản hồi, nên câu trả lời này đến từ thiết bị của bạn.",
  "res.textFallback": "Một phần chữ đã sửa được dùng phông khác, vì phông gốc không có các chữ đó: {fonts}.",
