  "res.targetMissed": "Tệp này không thể xuống dưới {target}. Mức nhỏ nhất chúng tôi làm được là {to} (trước là {from}), và đó là tệp bạn nhận. Chữ và hình vẽ không bị chuyển thành ảnh, nên chúng đặt ra mức sàn. Hãy thử cho phép thang xám, bỏ bớt trang hoặc chia tệp.",
  "res.underTarget": "Tệp này {size}, đã dưới {target}, nên không thay đổi.",
