  "res.examPadded": "Ngay cả ở chất lượng cao nhất vẫn dưới {min} KB, nên đã thêm một ghi chú ẩn để đạt mức đó. Ảnh không thay đổi.",
  "res.examTooBig": "Không thể xuống dưới {max} KB ở {w} x {h} px ngay cả với chất lượng thấp nhất; kết quả là {size}. Hãy thử thang xám, kích thước nhỏ hơn hoặc ảnh đơn giản hơn.",
  "res.lowerDpi": "Một số trang quá lớn với độ phân giải này, nên được tạo ở {dpi} DPI.",
