  "err.noTranslator": "Trình duyệt này không dịch được sang ngôn ngữ đó trên thiết bị này. Hãy tải mô hình lớn ở AI trên thiết bị, hoặc dùng Chrome trên máy tính, có sẵn trình dịch.",
  "err.cloudFailed": "AI máy chủ hiện không phản hồi, và thiết bị này không có trình dịch cho ngôn ngữ đó. Hãy thử lại sau, hoặc chọn Trên thiết bị này và tải Mô hình lớn về.",
  "err.noBookmarks": "PDF này không có dấu trang để chia. Hãy chia theo khoảng trang hoặc theo số trang.",
  "err.textEdit": "Không lưu được một phần chữ bạn đã sửa: chữ đó đã thay đổi từ lúc mở, hoặc không phông chữ nào sẵn có hiển thị được. Hãy hoàn tác thay đổi đó và thử lại.",
  "open.title": "Mở tệp",
  "open.subtitle": "Chọn công cụ cho các tệp này. Chúng ở lại trên thiết bị của bạn.",
  "open.files": "Tệp cần mở",
