  "open.noTool": "Không công cụ nào nhận tất cả các tệp này cùng lúc. Hãy chia sẻ từng loại tệp một.",
  "ws.bigBatch": "Tổng các tệp này là {size}, khá lớn với bộ nhớ của thiết bị này. Nếu trang chậm lại hoặc dừng, hãy xử lý theo từng nhóm nhỏ hơn.",
