  "choice.binding.left": "Bên trái",
  "choice.binding.right": "Bên phải (sách đọc từ phải sang trái)",
  "opt.blankLevel": "Độ nhạy",
  "choice.blankLevel.strict": "Nghiêm ngặt: chỉ trang hoàn toàn trống",
  "choice.blankLevel.normal": "Bình thường",
  "choice.blankLevel.lenient": "Nới lỏng: bỏ qua đốm bẩn và vết hằn",
  "opt.mixReverse": "Tệp thứ hai theo thứ tự ngược",
  "opt.hfHeader": "Đầu trang ({page}, {pages}, {filename} và {date} được tự điền)",
  "opt.hfFooter": "Chân trang",
  "opt.hfAlign": "Căn lề",
