  "listen.speed": "Tốc độ",
  "listen.voice": "Giọng đọc",
  "listen.voiceDefault": "Giọng mặc định",
  "listen.noVoice": "Thiết bị này không có giọng đọc cho ngôn ngữ của tài liệu, nên giọng mặc định được dùng. Bạn có thể thêm giọng trong phần cài đặt giọng nói của hệ thống.",
  "listen.noSpeech": "Trình duyệt này không đọc to văn bản được. Hãy thử phiên bản mới của Chrome, Edge, Safari hoặc Firefox.",
